<?php namespace App\Services; use Illuminate\Support\Facades\Http; class MailgunMailingList { public function ensure(string $address,string $name): bool {if(!config('services.mailgun.secret')) return false; return Http::withBasicAuth('api',config('services.mailgun.secret'))->asMultipart()->post('https://'.config('services.mailgun.endpoint').'/v3/lists',['address'=>$address,'name'=>$name,'access_level'=>'readonly'])->successful() || Http::withBasicAuth('api',config('services.mailgun.secret'))->get('https://'.config('services.mailgun.endpoint').'/v3/lists',['address'=>$address])->successful();} public function upsertMember(string $list,string $email,string $name): bool {return Http::withBasicAuth('api',config('services.mailgun.secret'))->asMultipart()->post('https://'.config('services.mailgun.endpoint').'/v3/lists/'.rawurlencode($list).'/members',['address'=>$email,'name'=>$name,'subscribed'=>'true','upsert'=>'true'])->successful();}}
